from itertools import combinations

def require(cond, msg):
    if not cond:
        raise RuntimeError(msg)

def three_frees(S):  # exact integer check: no nontrivial 3-term AP
    Sset = set(S)
    for i in range(len(S)):
        for j in range(i+1, len(S)):
            a, c = S[i], S[j]
            if (a + c) % 2 == 0:
                b = (a + c) // 2
                if b != a and b in Sset:
                    return False
    return True

def f3_exact(N):  # exhaustive: max size of 3-free subset of {1..N}
    for k in range(N, 0, -1):
        for S in combinations(range(1, N+1), k):
            if three_frees(S):
                return k, S
    return 0, ()

def alpha_HN(N):  # alpha(H_N) via independent-set definition, same integers
    # H_N edges = 3-term APs; independent set = 3AP-free set.
    # Exact identity check: recompute alpha by the hypergraph edge list.
    edges = [(a, b, c) for a in range(1, N+1)
             for c in range(a+2, N+1, 2) if (a+c) % 2 == 0
             for b in [ (a+c)//2 ] if b <= N and b > a]
    # brute force independent number over the explicit edge list
    for k in range(N, 0, -1):
        for S in combinations(range(1, N+1), k):
            Sset = set(S)
            ok = all(not (e[0] in Sset and e[1] in Sset and e[2] in Sset)
                     for e in edges)
